  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Hyperoside (quercetin 3-galactoside), a close structural analogue of the query quercetin 3-O-glucoside, was detected in rat brain after oral administration, demonstrating that quercetin glycosides can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cyanidin-3-O-glucoside, which shares the same 3-O-glucose attachment as the query, was detected in rat brain after blueberry feeding and intravenous administration, supporting brain uptake of 3-O-glucosylated flavonoid-type compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Cyanidin-3-O-glucoside reached approximately 3.5 nmol/g in mouse brain after intraperitoneal injection, providing quantitative evidence that a 3-O-glucosylated flavonoid-type compound achieves meaningful brain levels.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Intact cyanidin 3-galactoside was observed in pig brain, supporting brain access of glycosylated anthocyanins in a large-animal model and reinforcing the transferability of glycoside brain-penetration evidence.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: quercetin 3-O-glucoside is closely analogous to flavonol and anthocyanin glycosides with demonstrated brain detection after systemic administration; the weight of transferable evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental record for isoquercitrin itself; prediction relies on close structural analogues.",
    "Most records are qualitative brain-detection studies; quantitative unbound brain exposure and efflux-transporter status are not fully established.",
    "The relative contribution of intact glycoside versus aglycone or conjugated metabolites to brain levels is not completely resolved."
  ],
